def eratosthenes():
  N, R = 32, 5
  p = {i for i in range(2, N)}
  for i in range(2, R):
    if i in p:
      for j in range(i * i, N, i):
        p -= {j}
  return p


def repeatprimes():
  for _ in range(1000000):
    eratosthenes()
